package com.akshay.stockflow.auth;
import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.http.MediaType; import org.springframework.test.web.servlet.MockMvc; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc class AuthIntegrationTests {
@Autowired MockMvc mvc;
@Test void inventoryRequiresAuthentication() throws Exception {mvc.perform(get("/api/products")).andExpect(status().isUnauthorized());}
@Test void seededAdminCanLoginAndReadInventory() throws Exception {String body=mvc.perform(post("/api/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"email\":\"admin@stockflow.local\",\"password\":\"ChangeMe123!\"}")).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();String token=new com.fasterxml.jackson.databind.ObjectMapper().readTree(body).get("accessToken").asText();mvc.perform(get("/api/products").header("Authorization","Bearer "+token)).andExpect(status().isOk());}
@Test void publicRegistrationCannotGrantAdminRole() throws Exception {mvc.perform(post("/api/auth/register").contentType(MediaType.APPLICATION_JSON).content("{\"email\":\"new.employee@example.test\",\"password\":\"LongPassword123!\",\"fullName\":\"New Employee\",\"role\":\"ADMIN\"}")).andExpect(status().isCreated()).andExpect(jsonPath("$.role").value("EMPLOYEE"));}
@Test void employeeCannotCreateInventoryRecords() throws Exception {mvc.perform(post("/api/auth/register").contentType(MediaType.APPLICATION_JSON).content("{\"email\":\"readonly.employee@example.test\",\"password\":\"LongPassword123!\",\"fullName\":\"Read Only\"}")).andExpect(status().isCreated());String body=mvc.perform(post("/api/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"email\":\"readonly.employee@example.test\",\"password\":\"LongPassword123!\"}")).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();String token=new com.fasterxml.jackson.databind.ObjectMapper().readTree(body).get("accessToken").asText();mvc.perform(post("/api/products").header("Authorization","Bearer "+token).contentType(MediaType.APPLICATION_JSON).content("{\"name\":\"Forbidden Widget\",\"sku\":\"FORBIDDEN-01\",\"category\":\"Test\",\"warehouse\":\"Test\",\"quantity\":1,\"reorderLevel\":0,\"unitPrice\":1}")).andExpect(status().isForbidden());}
@Test void disabledAccountCannotReusePreviouslyIssuedJwt() throws Exception {String registered=mvc.perform(post("/api/auth/register").contentType(MediaType.APPLICATION_JSON).content("{\"email\":\"disabled.user@example.test\",\"password\":\"LongPassword123!\",\"fullName\":\"Disabled User\"}")).andExpect(status().isCreated()).andReturn().getResponse().getContentAsString();long id=new com.fasterxml.jackson.databind.ObjectMapper().readTree(registered).get("id").asLong();String login=mvc.perform(post("/api/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"email\":\"disabled.user@example.test\",\"password\":\"LongPassword123!\"}")).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();String token=new com.fasterxml.jackson.databind.ObjectMapper().readTree(login).get("accessToken").asText();String admin=mvc.perform(post("/api/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"email\":\"admin@stockflow.local\",\"password\":\"ChangeMe123!\"}")).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();String adminToken=new com.fasterxml.jackson.databind.ObjectMapper().readTree(admin).get("accessToken").asText();mvc.perform(patch("/api/admin/users/"+id+"/status").header("Authorization","Bearer "+adminToken).contentType(MediaType.APPLICATION_JSON).content("{\"enabled\":false}")).andExpect(status().isOk());mvc.perform(get("/api/products").header("Authorization","Bearer "+token)).andExpect(status().isUnauthorized());}
}
